import { connectMarket, INTERVALS } from './market-data.mjs';
import { mountDashboard, icon, ASSETS, money, percentage, escapeHTML } from './dashboard.mjs';
export const TRADE_MARKETS=ASSETS.filter(a=>['BTC','ETH','BNB','SOL','XRP'].includes(a.symbol));
export function orderPreview(price,amount){const p=Number(price),a=Number(amount);if(!Number.isFinite(p)||!Number.isFinite(a)||p<=0||a<=0)return {total:0};const total=p*a;return Number.isFinite(total)?{total}:{total:0};}
export function priceChart(asset,timeframe,type,candles=[]){
 if(!candles.length)return '<p class="trade-muted trade-no-results">Waiting for market candles…</p>';
 const bars=candles.slice(-56),low=Math.min(...bars.map(c=>c.low)),high=Math.max(...bars.map(c=>c.high)),padding=Math.max((high-low)*.08,high*.0001),min=low-padding,max=high+padding,y=p=>280-(p-min)/(max-min)*250,x=i=>18+i*550/Math.max(1,bars.length-1),points=bars.map((c,i)=>x(i)+','+y(c.close)).join(' ');
 const grid=[0,1,2,3,4].map(i=>{const value=max-(max-min)*i/4,py=y(value);return '<line x1="0" x2="580" y1="'+py+'" y2="'+py+'" stroke="#202b25"/><text x="590" y="'+(py+4)+'" fill="#82988b" font-size="10">'+value.toLocaleString('en-US',{maximumFractionDigits:4})+'</text>';}).join('');
 const shape=type==='Candle'?bars.map((c,i)=>{const color=c.close>=c.open?'#00d987':'#f24f65';return '<line x1="'+x(i)+'" x2="'+x(i)+'" y1="'+y(c.high)+'" y2="'+y(c.low)+'" stroke="'+color+'"/><rect x="'+(x(i)-3)+'" y="'+y(Math.max(c.open,c.close))+'" width="6" height="'+Math.max(1,Math.abs(y(c.open)-y(c.close)))+'" fill="'+color+'"/>';}).join(''):(type==='Area'?'<polygon points="18,280 '+points+' 568,280" fill="#00ed8722"/>':'')+'<polyline points="'+points+'" fill="none" stroke="#00ed87" stroke-width="2"/>';
 const labels=[0,Math.floor((bars.length-1)/2),bars.length-1].map(i=>'<text x="'+x(i)+'" y="318" fill="#82988b" font-size="10" text-anchor="'+(i===0?'start':i===bars.length-1?'end':'middle')+'">'+new Date(bars[i].time*1000).toLocaleDateString(undefined,{month:'short',day:'numeric'})+' '+new Date(bars[i].time*1000).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})+'</text>').join('');
 return '<svg class="trade-chart-svg" viewBox="0 0 690 330" role="img" aria-label="'+asset.symbol+' '+timeframe+' '+type+' market chart">'+grid+shape+labels+'</svg>';
}
function marketRows(query='',tickers={}){return TRADE_MARKETS.filter(a=>(a.symbol+' '+a.name).toLowerCase().includes(query.toLowerCase().trim())).map(original=>{const a={...original,price:tickers[original.symbol+'/USDT']?.last,change:tickers[original.symbol+'/USDT']?.change_pct};return '<button class="trade-market-row" data-pair="'+a.symbol+'"><span><img src="/assets/'+a.icon+'@2x.png" alt=""><span><strong>'+a.symbol+'</strong><small>USDT</small></span></span><span>'+(Number.isFinite(a.price)?money(a.price):'—')+'</span><span class="'+(a.change>=0?'positive':'negative')+'">'+(Number.isFinite(a.change)?percentage(a.change):'—')+'</span></button>';}).join('')||'<p class="trade-muted trade-no-results">No matching markets</p>';}
export function tradeHTML(){return '<div class="trade-workspace"><div class="trade-demo">'+icon('shield')+' Kraken market data · <span id="trade-feed-status" role="status">Connecting</span> · Order execution is not connected</div><div class="trade-grid"><aside class="trade-panel trade-markets"><h2>Markets</h2><label class="trade-market-search">'+icon('search')+'<input id="trade-market-search" type="search" placeholder="Search pairs..." aria-label="Search trading pairs"></label><div class="trade-market-labels"><span>Pair</span><span>Price</span><span>24h</span></div><div id="trade-market-rows">'+marketRows()+'</div></aside><section class="trade-panel trade-chart-panel" aria-label="Price chart"><div id="trade-market-heading"></div><div class="trade-chart-toolbar"><div class="trade-segments" aria-label="Chart timeframe">'+['1H','4H','1D','1W'].map(t=>'<button data-timeframe="'+t+'" aria-pressed="'+(t==='1H')+'">'+t+'</button>').join('')+'</div><div class="trade-segments" aria-label="Chart style">'+['Candle','Line','Area'].map(t=>'<button data-chart-type="'+t+'" aria-pressed="'+(t==='Candle')+'">'+t+'</button>').join('')+'</div></div><div id="trade-price-chart"></div><div class="trade-chart-caption">Source: Kraken · Prices quoted in USDT · Times shown in your local timezone</div></section><section class="trade-panel trade-book" aria-labelledby="order-book-title"><div class="trade-panel-title"><h2 id="order-book-title">Order Book</h2><div class="trade-segments">'+['Both','Bids','Asks'].map(t=>'<button data-book="'+t+'" aria-pressed="'+(t==='Both')+'">'+t+'</button>').join('')+'</div></div><div class="trade-book-head"><span>Price</span><span>Amount</span><span>Total</span></div><div id="trade-book-rows"></div><div class="trade-recent"><h2>Recent Trades</h2><div class="trade-book-head"><span>Price</span><span>Amount</span><span>Time</span></div><div id="trade-recent-rows"></div></div></section><section class="trade-panel trade-order" aria-label="Order preview"><div class="trade-side-tabs"><button data-side="Buy" aria-pressed="true">Buy</button><button data-side="Sell" aria-pressed="false">Sell</button></div><div class="trade-segments trade-order-types"><button data-order-type="Limit" aria-pressed="true">Limit</button><button data-order-type="Market" aria-pressed="false">Market</button></div><form id="trade-order-form"><label for="trade-order-price">Price (USDT)</label><input id="trade-order-price" type="number" min="0.000001" step="any" required><label for="trade-order-amount" id="trade-amount-label">Amount (BTC)</label><input id="trade-order-amount" type="number" min="0" step="any" value="0.00" required><input id="trade-allocation" type="range" min="0" max="100" value="0" aria-label="Balance allocation"><div class="trade-allocation-labels">'+[25,50,75,100].map(n=>'<button type="button" data-allocation="'+n+'">'+n+'%</button>').join('')+'</div><label for="trade-order-total">Total (USDT)</label><input id="trade-order-total" value="0.00" readonly><dl class="trade-order-summary"><div><dt>Fee (not configured)</dt><dd id="trade-order-fee">—</dd></div><div><dt id="trade-available-label">Available (USDT)</dt><dd id="trade-available">Wallet not connected</dd></div></dl><button type="submit" id="trade-submit" class="deposit-continue">Buy BTC</button><p id="trade-order-feedback" role="status" class="transfer-placeholder-note" hidden></p><p class="trade-order-disclaimer">Preview only. No orders or balance changes are created.</p></form></section><section class="trade-panel trade-orders" aria-label="Trading activity"><div class="trade-activity-tabs">'+['Orders','History','Positions'].map(t=>'<button data-activity="'+t+'" aria-pressed="'+(t==='Orders')+'">'+icon(t==='History'?'volume':t==='Positions'?'wallet':'markets')+t+'</button>').join('')+'</div><div class="trade-empty-activity" id="trade-activity-content">'+icon('markets')+'<p>No open orders</p><small>Orders will appear here when trading is connected.</small></div></section></div></div>';}
export function mountTrade(root,options={}){mountDashboard(root,{...options,view:'trade',mainHTML:tradeHTML()});const main=root.querySelector('main');let asset=TRADE_MARKETS.find(a=>a.symbol==='BTC'),timeframe='1H',type='Candle',side='Buy',orderType='Limit',book='Both';let live={tickers:{},candles:[],bids:[],asks:[],trades:[],errors:{}},feed,paintTimer; const price=main.querySelector('#trade-order-price'),amount=main.querySelector('#trade-order-amount'),feedback=main.querySelector('#trade-order-feedback');
function updateTotals(){const result=orderPreview(price.value,amount.value);main.querySelector('#trade-order-total').value=result.total.toFixed(2);main.querySelector('#trade-order-fee').textContent='Not configured';feedback.hidden=true;}
function rows(sell){const entries=(sell?[...live.asks].slice(0,8).reverse():live.bids.slice(0,8)),max=Math.max(...entries.map(x=>x.qty),1);return entries.map(x=>'<div class="trade-book-row '+(sell?'ask':'bid')+'" style="--depth:'+Math.round(x.qty/max*100)+'%"><span>'+x.price.toLocaleString('en-US',{maximumFractionDigits:4})+'</span><span>'+x.qty.toFixed(4)+'</span><span>'+(x.price*x.qty).toFixed(2)+'</span></div>').join('');}
function renderBook(){main.querySelector('#trade-book-rows').innerHTML=live.bids.length||live.asks.length?(book!=='Bids'?rows(true):'')+'<div class="trade-book-mid">'+(Number.isFinite(asset.price)?money(asset.price):'—')+'</div>'+(book!=='Asks'?rows(false):''):'<p class="trade-muted">Waiting for order book…</p>';main.querySelector('#trade-recent-rows').innerHTML=live.trades.length?live.trades.slice(0,7).map(t=>'<div class="trade-book-row '+(t.side==='buy'?'bid':'ask')+'"><span>'+Number(t.price).toLocaleString('en-US',{maximumFractionDigits:4})+'</span><span>'+Number(t.qty).toFixed(4)+'</span><span>'+new Date(t.timestamp).toLocaleTimeString()+'</span></div>').join(''):'<p class="trade-muted">Waiting for recent trades…</p>';}
function renderChart(){main.querySelector('#trade-price-chart').innerHTML=priceChart(asset,timeframe,type,live.candles);main.querySelector('.trade-chart-caption').textContent='Source: Kraken · USDT · Local time'+(live.historyError?' · Historical candles unavailable, showing streamed candles':'')+(Object.keys(live.errors).length?' · Some market subscriptions unavailable':'');}
function updateSide(){main.querySelector('#trade-amount-label').textContent='Amount ('+asset.symbol+')';main.querySelector('#trade-submit').textContent=side+' '+asset.symbol;main.querySelector('#trade-submit').classList.toggle('sell',side==='Sell');main.querySelector('#trade-available-label').textContent='Available ('+(side==='Buy'?'USDT':asset.symbol)+')';main.querySelector('#trade-available').textContent='Wallet not connected';feedback.hidden=true;}
function renderMarket(reset=false){const ticker=live.tickers[asset.symbol+'/USDT'];asset={...asset,price:ticker?.last,change:ticker?.change_pct};const show=n=>Number.isFinite(n)?money(n):'—';main.querySelector('#trade-market-heading').innerHTML='<div class="trade-pair-title"><img src="/assets/'+asset.icon+'@2x.png" alt=""><div><h1>'+asset.symbol+'/USDT</h1><span>'+escapeHTML(asset.name)+'</span></div><div class="trade-live-price"><strong>'+show(asset.price)+'</strong><span>'+(Number.isFinite(asset.change)?percentage(asset.change):'—')+'</span></div></div><dl class="trade-market-stats"><div><dt>24h High</dt><dd>'+show(ticker?.high)+'</dd></div><div><dt>24h Low</dt><dd>'+show(ticker?.low)+'</dd></div><div><dt>24h Volume ('+asset.symbol+')</dt><dd>'+(Number.isFinite(ticker?.volume)?ticker.volume.toLocaleString():'—')+'</dd></div></dl>';
 if(reset){price.value=asset.price||'';amount.value='0.00';main.querySelector('#trade-allocation').value=0;updateSide();updateTotals();}else if(orderType==='Market'||!price.value){price.value=asset.price||'';updateTotals();}
 main.querySelectorAll('[data-pair]').forEach(b=>{const t=live.tickers[b.dataset.pair+'/USDT'];b.setAttribute('aria-pressed',b.dataset.pair===asset.symbol);b.children[1].textContent=Number.isFinite(t?.last)?money(t.last):'—';b.children[2].textContent=Number.isFinite(t?.change_pct)?percentage(t.change_pct):'—';b.children[2].className=t?.change_pct>=0?'positive':'negative';});renderChart();renderBook();}
function pressed(selector,target){main.querySelectorAll(selector).forEach(b=>b.setAttribute('aria-pressed',b===target));}
main.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pair){asset=TRADE_MARKETS.find(a=>a.symbol===b.dataset.pair);feed.select(asset.symbol+'/USDT',INTERVALS[timeframe]);renderMarket(true);}if(b.dataset.timeframe){timeframe=b.dataset.timeframe;pressed('[data-timeframe]',b);feed.select(asset.symbol+'/USDT',INTERVALS[timeframe]);renderChart();}if(b.dataset.chartType){type=b.dataset.chartType;pressed('[data-chart-type]',b);renderChart();}if(b.dataset.book){book=b.dataset.book;pressed('[data-book]',b);renderBook();}if(b.dataset.side){side=b.dataset.side;pressed('[data-side]',b);updateSide();}if(b.dataset.orderType){orderType=b.dataset.orderType;price.readOnly=orderType==='Market';if(price.readOnly)price.value=asset.price;pressed('[data-order-type]',b);updateTotals();}if(b.dataset.allocation){main.querySelector('#trade-allocation').value=b.dataset.allocation;amount.value='0.00';updateTotals();feedback.hidden=false;feedback.textContent='Wallet balances are not connected. Allocation is unavailable.';}if(b.dataset.activity){pressed('[data-activity]',b);const messages={Orders:['No open orders','Orders will appear here when trading is connected.'],History:['No trade history','Completed trades will appear here.'],Positions:['No open positions','Positions will appear here when trading is connected.']},message=messages[b.dataset.activity];main.querySelector('#trade-activity-content').innerHTML=icon('markets')+'<p>'+message[0]+'</p><small>'+message[1]+'</small>';}};
main.querySelector('#trade-market-search').oninput=e=>{main.querySelector('#trade-market-rows').innerHTML=marketRows(e.target.value,live.tickers);main.querySelectorAll('[data-pair]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.pair===asset.symbol));};price.oninput=updateTotals;amount.oninput=updateTotals;main.querySelector('#trade-allocation').oninput=()=>{amount.value='0.00';updateTotals();};main.querySelector('#trade-order-form').onsubmit=e=>{e.preventDefault();feedback.hidden=false;feedback.textContent=side+' '+asset.symbol+' '+orderType.toLowerCase()+' order preview only. Nothing was submitted. No funds were moved.';};renderMarket(true);
feed=connectMarket({symbols:TRADE_MARKETS.map(a=>a.symbol+'/USDT'),symbol:asset.symbol+'/USDT',interval:INTERVALS[timeframe],onData:data=>{live=data;if(!paintTimer)paintTimer=setTimeout(()=>{paintTimer=null;if(main.isConnected)renderMarket();},150);},onStatus:status=>{if(main.isConnected)main.querySelector('#trade-feed-status').textContent=status;}});
const cleanup=()=>{feed.close();clearTimeout(paintTimer);observer.disconnect();window.removeEventListener('pagehide',cleanup);};const observer=new MutationObserver(()=>{if(!main.isConnected)cleanup();});observer.observe(root,{childList:true});window.addEventListener('pagehide',cleanup,{once:true});window.scrollTo(0,0);return cleanup;}
